param([string]$OutputDir=(Join-Path $PSScriptRoot '..\data\generated\generic_two_by_three'))
$ErrorActionPreference='Stop';$out=[IO.Path]::GetFullPath($OutputDir);$log=Get-Content -Raw -LiteralPath (Join-Path $out 'generic_cpp_run.log');$rp=Join-Path $out 'validation_report.txt'
foreach($p in @('Domains: 3','interface 0: .*overlap_ratio=1','interface 1: .*overlap_ratio=1','interface 2: .*overlap_ratio=1','\[Schwarz-Precond-FGMRES\] step 100','Schwarz-Precond-FGMRES \[success\]')){if($log -notmatch $p){throw "Missing regression evidence: $p"}}
$m=[regex]::Match($log,'step 100\s+time=\s*100 s\s+Tmin=\s*([^\s]+)\s+Tmax=\s*([^\s]+)\s+Tavg=\s*([^\s]+)\s+interface_avg_jump=([^\s]+).*?rel_residual=([^\s]+)');$it=[regex]::Match($log,'total_iterations=(\d+)');if(!$m.Success -or !$it.Success){throw 'Cannot parse final solver result.'}
$base=(Get-Content -Raw -LiteralPath $rp)-replace '(?s)\r?\nC\+\+ generic regression:.*$','';$tail="`r`nC++ generic regression: PASS`r`nTmin=$($m.Groups[1].Value) Tmax=$($m.Groups[2].Value) Tavg=$($m.Groups[3].Value) interface_jump=$($m.Groups[4].Value) final_residual=$($m.Groups[5].Value) total_iterations=$($it.Groups[1].Value)`r`n`r`n=== GENERIC TWO-BY-THREE REGRESSION PASSED ===`r`n";Set-Content -LiteralPath $rp -Value ($base.TrimEnd()+$tail)
